 synGraphHandle graph;ck(synGraphCreate(&graph,synDeviceGaudi2),"graph");std::vector<Buffer>buffers;buffers.reserve(8);
 auto tensor=[&](std::string name,synDataType type,int x,int y,unsigned size,bool output=false,int z=1){synTensorDescriptor d{};d.m_name=name.c_str();d.m_dataType=type;d.m_dims=z==1?2:3;d.m_sizes[2]=d.m_minSizes[2]=z;d.m_sizes[0]=d.m_minSizes[0]=x;d.m_sizes[1]=d.m_minSizes[1]=y;synSectionHandle section;ck(synSectionCreate(&section,0,graph),"section");ck(synSectionSetPersistent(section,true),"persistent");Buffer b{name,nullptr,uint64_t(x)*y*z*size,0,nullptr,output};ck(synTensorCreate(&b.tensor,&d,section,0),"tensor");ck(synHostMalloc(device,b.bytes,0,&b.host),"host");ck(synDeviceMalloc(device,b.bytes,0,0,&b.addr),"device");if(name!="lut"&&name!="directions"&&!output){auto data=read(dir+"/"+((mode=="old"&&(name=="packed"||name=="scales"))?"legacy_":"")+name+".bin");if(data.size()!=b.bytes)throw std::runtime_error("input bytes");std::memcpy(b.host,data.data(),b.bytes);}else std::memset(b.host,0,b.bytes);buffers.push_back(b);return b.tensor;};
