 uint64_t bytes=0,workspace=0;ck(synWorkspaceGetSize(&bytes,recipe),"workspace");if(bytes)ck(synDeviceMalloc(device,bytes,0,0,&workspace),"workspace alloc");auto run=[&](){ck(synLaunch(stream,launch.data(),launch.size(),workspace,recipe,SYN_FLAGS_TENSOR_NAME),"launch");};run();auto&output=*std::find_if(buffers.begin(),buffers.end(),[](const Buffer&b){return b.output;});ck(synMemCopyAsync(stream,output.addr,output.bytes,uint64_t(output.host),DRAM_TO_HOST),"d2h");for(auto&b:buffers)if(b.output)ck(synMemCopyAsync(stream,b.addr,b.bytes,uint64_t(b.host),DRAM_TO_HOST),"output d2h");ck(synStreamSynchronize(stream),"sync");for(auto&b:buffers)if(b.output)save(b.name+".bin",b.host,b.bytes);auto&overflow_buffer=*std::find_if(buffers.begin(),buffers.end(),[](const Buffer&b){return b.name=="overflow";});for(int expert=0;expert<e;++expert)if(((int*)overflow_buffer.host)[expert])throw std::runtime_error("capacity overflow");
 if(mode=="gate"){auto&reference=*std::find_if(buffers.begin(),buffers.end(),[](const Buffer&b){return b.name=="reference_gate";});unsigned bad=0;for(uint64_t i=0;i<output.bytes/2;++i)bad+=((uint16_t*)output.host)[i]!=((uint16_t*)reference.host)[i];std::printf("{\"stage\":\"gate_boundary\",\"checked\":%llu,\"bit_mismatches\":%u,\"scope\":\"correctness and placement; includes literal reference gate; no timing\"}\n",(unsigned long long)(output.bytes/2),bad);if(bad)throw std::runtime_error("GP BF16 boundary mismatch");ck(synDeviceRelease(device),"release");acquired=false;ck(synDestroy(),"destroy");initialized=false;return 0;}
 auto refraw=read(dir+"/reference.f64"),absraw=read(dir+"/sumabs.f64");save("reference.f64",refraw.data(),refraw.size());save("sumabs.f64",absraw.data(),absraw.size());auto*ref=(double*)refraw.data();auto*norm=(double*)absraw.data();auto*value=(float*)output.host;unsigned bad=0;double maxback=0,maxerr=0;for(int i=0;i<n*t;++i){double delta=std::abs(double(value[i])-ref[i]);bad+=!std::isfinite(value[i])||delta>2e-6*norm[i]+1e-35;maxerr=std::max(maxerr,delta);maxback=std::max(maxback,delta/std::max(norm[i],1e-300));}
 std::printf("{\"stage\":\"gate\",\"checked\":%d,\"bad\":%u,\"max_abs\":%.12g,\"max_backward\":%.12g,\"workspace\":%llu,\"compute_nodes\":%u}\n",n*t,bad,maxerr,maxback,(unsigned long long)bytes,resources.budget.decode_nodes+resources.budget.mme_nodes+resources.budget.combine_nodes+1);std::fflush(stdout);if(bad)throw std::runtime_error("full output gate");for(int i=0;i<10;++i)run();ck(synStreamSynchronize(stream),"warmup");synEventHandle begin,end;ck(synEventCreate(&begin,device,EVENT_COLLECT_TIME),"event");ck(synEventCreate(&end,device,EVENT_COLLECT_TIME),"event");for(int sample=0;sample<5;++sample){auto wall=std::chrono::steady_clock::now();ck(synEventRecord(begin,stream),"start");for(int j=0;j<repeats;++j)run();ck(synEventRecord(end,stream),"end");ck(synEventSynchronize(end),"event sync");uint64_t ns;ck(synEventElapsedTime(&ns,begin,end),"elapsed");double us=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-wall).count()/repeats;std::printf("{\"stage\":\"timing\",\"sample\":%d,\"event_us\":%.6f,\"wall_us\":%.6f}\n",sample,double(ns)/1000/repeats,us);}
